[CmdletBinding()]
param([switch]$NoPush, [switch]$WhatIfMode)
. (Join-Path $PSScriptRoot 'scripts\publish-common.ps1')

Push-Location $PSScriptRoot
try {
    $branch = Invoke-RepositoryGit -Arguments @('branch', '--show-current') -Capture
    & (Join-Path $PSScriptRoot 'build.ps1')
    $version = Get-PublishVersion
    if ($branch -ne 'main' -or $WhatIfMode) {
        Write-Host "Test-only release on '$branch': would use $version and release/rel-$version.txt."
        Write-Host 'Read-only rehearsal: no files changed, prompts, commits, tags, or pushes.'
        return
    }
    Assert-CleanTree
    $notesPath = Join-Path $PSScriptRoot 'RELEASE_NOTES.md'
    $stylePath = Join-Path $PSScriptRoot 'RELEASE_NOTES_STYLE.md'
    if (-not (Test-Path $stylePath)) { throw 'RELEASE_NOTES_STYLE.md is required.' }
    $notesBefore = if (Test-Path $notesPath) { Get-Content $notesPath -Raw } else { '' }
    if (Invoke-RepositoryGit -Arguments @('tag', '--list', $version) -Capture) {
        throw "Timestamp tag already exists: $version. Wait for the next UTC minute."
    }
    if (-not $NoPush) {
        $remoteTag = Invoke-RepositoryGit -Arguments @('ls-remote', '--tags', 'origin', "refs/tags/$version") -Capture
        if ($remoteTag) { throw "Timestamp tag already exists on origin: $version." }
    }
    $tags = (Invoke-RepositoryGit -Arguments @('tag', '--merged', 'HEAD', '--sort=-refname') -Capture) -split "`n"
    $previousTag = $tags | Where-Object { $_ -match '^\d{4}-\d{2}-\d{2}-\d{2}-\d{2}$' } | Select-Object -First 1
    $base = if ($previousTag) { $previousTag } else {
        # Hashing the empty tree includes the complete initial snapshot, not just the latest commit.
        $emptyTree = @() | & git hash-object -t tree --stdin
        if ($LASTEXITCODE -ne 0) { throw 'Unable to compute empty tree for first release.' }
        $emptyTree
    }
    $oldCompleted = @(Get-PmItems -Root $PSScriptRoot -Folder 'completed')
    $candidates = @(Get-PmItems -Root $PSScriptRoot -Folder 'release-candidate')
    Write-Host "Release $version includes $($candidates.Count) production candidates and retires $($oldCompleted.Count) previous completed items."
    if ((Read-Host 'Prepare this release and its PM transitions? [prepare/cancel]') -cne 'prepare') {
        throw 'Release cancelled; no changes made.'
    }

    if ($oldCompleted.Count -gt 0) {
        foreach ($item in $oldCompleted) { Remove-Item -LiteralPath $item.FullName }
        Update-PmIndex -Root $PSScriptRoot
        Invoke-RepositoryGit -Arguments @('add', '--', 'PM')
        Invoke-RepositoryGit -Arguments @('commit', '-m', 'chore: retire previous release PM items', '-m',
            'Co-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>')
    }
    foreach ($item in $candidates) {
        Add-Content -LiteralPath $item.FullName -Value "`n## Production release`nIncluded in $version." -Encoding utf8
        Move-PmItem -Root $PSScriptRoot -Item $item -Destination 'completed'
    }
    Update-PmIndex -Root $PSScriptRoot
    Set-PublishVersion -Root $PSScriptRoot -Version $version
    & (Join-Path $PSScriptRoot 'build.ps1')
    # Stage moved PM records so the audit includes their new paths and contents.
    Invoke-RepositoryGit -Arguments @('add', '--', 'docs', 'PM')

    $releaseDirectory = Join-Path $PSScriptRoot 'release'
    New-Item -ItemType Directory -Path $releaseDirectory -Force | Out-Null
    $diffPath = Join-Path $releaseDirectory "rel-$version.txt"
    if (Test-Path $diffPath) { throw "Release audit already exists: $diffPath" }
    $diffArguments = @('diff', '--binary', $base, '--', '.', ':(exclude)release',
        ':(exclude)RELEASE_NOTES.md')
    $diffBody = Invoke-RepositoryGit -Arguments $diffArguments -Capture
    $audit = (New-OriginHeader) -split "`n" | ForEach-Object { "# $_" }
    $audit += "# Release timestamp: $version", "# Diff base: $base", '# Scope: all tracked changes including version and PM transitions; excludes release audits and release notes.', '', $diffBody
    Set-Content -LiteralPath $diffPath -Value ($audit -join "`n") -Encoding utf8
    $preparedDiff = $diffBody
    $preparedHead = Invoke-RepositoryGit -Arguments @('rev-parse', 'HEAD') -Capture
    $releaseNotesDirective = @"
AI RELEASE-NOTES DIRECTIVE:
Read release/rel-$version.txt completely and RELEASE_NOTES_STYLE.md.
Read PM/completed item files for this release. Replace RELEASE_NOTES.md with
only diff-supported, user-facing changes. Use '# Release $version' after its
origin breadcrumb. Preserve the breadcrumb; do not claim unimplemented gameplay.
Then return here for explicit developer confirmation.
"@
    try {
        Set-Clipboard -Value $releaseNotesDirective -ErrorAction Stop
        Write-Host 'AI release-notes directive copied to the clipboard.'
    } catch {
        Write-Warning "Could not copy the AI release-notes directive to the clipboard: $($_.Exception.Message)"
        Write-Host 'Copy the directive below manually:'
        Write-Host $releaseNotesDirective
    }
    if (-not (Test-Path $notesPath)) {
        Set-Content -LiteralPath $notesPath -Value ("<!--`n$(New-OriginHeader)`n-->`n") -Encoding utf8
    }
    $releaseChoice = Read-Host 'Confirm RELEASE_NOTES.md was updated from the evidence. [R]elease [C]ancel'
    $releaseChoice = ([string]$releaseChoice).Trim().ToUpperInvariant()
    switch ($releaseChoice) {
        'R' { }
        'C' { throw 'Release cancelled. Prepared files remain for review; no release commit, tag, or push was made.' }
        default { throw 'Invalid choice. Release cancelled; prepared files remain for review and no release commit, tag, or push was made.' }
    }
    $notes = Get-Content $notesPath -Raw
    if ($notes -eq $notesBefore -or $notes -notmatch '(?s)\A<!--.*?Generated by project-toolkit.*?-->') {
        throw 'Release notes must change and preserve an origin breadcrumb.'
    }
    if ($notes -notmatch "(?m)^# Release $([regex]::Escape($version))\s*$" -or $notes -notmatch '(?m)^## Overview\s*$') {
        throw 'Release notes need the exact timestamp heading and Overview section.'
    }
    if ((Invoke-RepositoryGit -Arguments @('branch', '--show-current') -Capture) -ne 'main' -or
        (Invoke-RepositoryGit -Arguments @('rev-parse', 'HEAD') -Capture) -ne $preparedHead) {
        throw 'Branch or HEAD changed during the notes gate; aborting.'
    }
    if ((Invoke-RepositoryGit -Arguments $diffArguments -Capture) -cne $preparedDiff) {
        throw 'Release contents changed during the notes gate. Regenerate evidence before releasing.'
    }
    $untracked = Invoke-RepositoryGit -Arguments @('ls-files', '--others', '--exclude-standard') -Capture
    foreach ($path in ($untracked -split "`n" | Where-Object { $_ })) {
        if ($path -notin @("release/rel-$version.txt", 'RELEASE_NOTES.md')) {
            throw "Unexpected untracked file during release: $path"
        }
    }
    if ((Get-Content $diffPath -Raw).TrimEnd() -cne ($audit -join "`n").TrimEnd()) {
        throw 'Release audit changed during the notes gate.'
    }
    Invoke-RepositoryGit -Arguments @('add', '--', 'docs', 'PM', 'RELEASE_NOTES.md', "release/rel-$version.txt")
    Invoke-RepositoryGit -Arguments @('commit', '-m', "release: $version", '-m',
        'Co-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>')
    Assert-CleanTree
    Invoke-RepositoryGit -Arguments @('tag', '-a', $version, '-m', "Release $version")
    if ($NoPush) { Write-Host "NoPush: release $version committed and tagged locally."; return }
    Invoke-RepositoryGit -Arguments @('push', '--atomic', 'origin', 'main', "refs/tags/$version")
    Write-Host "Released $version. GitHub Actions will create the GitHub Release."
} finally {
    Pop-Location
}
